-- ============================================================================
-- WOW FOREVER - REZEPT-FUNDORTE: HANDELSKOMMISSION VON AZEROTH (DEUTSCH)
-- ============================================================================
-- Quelle: Wowhead-Guide "Azeroth Commerce Authority" (Stand: Forever-BETA,
-- 24.09.2026) - Namen, Skill und Preise können sich bis zum Release ändern!
-- https://www.wowhead.com/forever/de/guide/azeroth-commerce-authority-reputation-professions
--
-- Nur aktiv, wenn der Spielversions-Button auf FOREVER steht.
-- Allianz-Lager: Drei Ecken, Rotkammgebirge (10.5, 72.7).
-- Horde: "Durator Supply & Logistics", Brachland (42, 34) - Händlernamen
-- der Horde sind noch nicht bekannt.
--
-- Deutsche Namen gibt es bisher nur für Alchimie, Verzauberkunst und
-- Ingenieurskunst. Für Schmiedekunst, Schneidern, Lederverarbeitung und
-- Kochkunst stehen vorerst die ENGLISCHEN Namen drin (so wie auf der
-- deutschen Wowhead-Seite) - bitte ersetzen, sobald die Übersetzung da ist.

BerufeFundorteDB_Forever = BerufeFundorteDB_Forever or {}

if GetLocale() == "deDE" then

local function Eintrag(name, beruf, typ, haendler, koords, skill, preis, hinweis)
    BerufeFundorteDB_Forever[name] = string.format(
        "|cff59ccff[Forever]|r %s vom Händler (nicht beim Lehrer)\n" ..
        "Verkauft von: %s (Handelskommission von Azeroth)\n" ..
        "Ort: Rotkammgebirge, Lager Drei Ecken (%s) - Allianz\n" ..
        "Horde: Lager von Durator Supply & Logistics, Brachland (42, 34)\n" ..
        "Benötigt: %s %d\nPreis: %d Händlergunst (Merchants' Favor)\n%s" ..
        "|cff888888(Forever-Beta, Angaben ohne Gewähr)|r",
        typ, haendler, koords, beruf, skill, preis, hinweis or "")
    -- Wegpunkt-Daten (Wegpunkt.lua): Allianz = Händler im Lager Drei Ecken
    -- (Rotkammgebirge, uiMapID 1433), Horde = Lager von Durator (Brachland,
    -- uiMapID 1413, genaue Händlerposition noch unbekannt).
    local ax, ay = koords:match("([%d%.]+),%s*([%d%.]+)")
    BerufeFundorteDB_Forever[name .. "_AZone"] = 1433
    BerufeFundorteDB_Forever[name .. "_AX"] = tonumber(ax)
    BerufeFundorteDB_Forever[name .. "_AY"] = tonumber(ay)
    BerufeFundorteDB_Forever[name .. "_HZone"] = 1413
    BerufeFundorteDB_Forever[name .. "_HX"] = 42.0
    BerufeFundorteDB_Forever[name .. "_HY"] = 34.0
end


